Lemma havoc_units_out x y t h o tko :
  x mod 16 = 0 -> ~ (x <= o < y) ->
  match tko with Some tk => hl_ticks (default [] (h !! (o / 16))) t | None => True end ->
  stale (default [] (havoc_units x y t h !! (o / 16))) (o mod 16) tko = stale (default [] (h !! (o / 16))) (o mod 16) tko.
